<script setup>
import { computed, ref } from 'vue'; import { useRoute } from 'vue-router'; import { showToast } from 'vant'; import AppLogo from '@/components/common/AppLogo.vue'; import AppNotice from '@/components/common/AppNotice.vue'; import { areaOptions } from '@/mock/common/area'; import { startNotice } from '@/mock/home/notice'; import { useLocalUser } from '@/composables/useLocalUser'; import { useNavigator } from '@/composables/useNavigator'; import logo from '@/assets/svgs/logo/logo-start.svg'; import arrowIcon from '@/assets/svgs/action/icon-arrow-right.svg'; import closeIcon from '@/assets/svgs/action/icon-close.svg'
const route = useRoute(); const { phone, address, saveUser } = useLocalUser(); const { goHome, goUser } = useNavigator(); const localAddress = ref(address.value); const areaValue = ref(''); const showArea = ref(false); const buttonText = computed(() => route.query.from === 'user' ? '进入用户' : '进入首页')
const finish = ({ selectedOptions }) => { localAddress.value = selectedOptions.map((item) => item.text).join('/'); showArea.value = false }
const enter = () => { if (!/^1\d{10}$/.test(phone.value)) return showToast('请输入正确的11位手机号'); if (!localAddress.value) return showToast('请选择服务区域'); saveUser(phone.value, localAddress.value); route.query.from === 'user' ? goUser() : goHome() }
</script>
<template><main class="mobile-page"><AppNotice :text="startNotice"/><section class="start"><AppLogo :src="logo"/><h1>发现身边的好服务</h1><p>选择所在区域，浏览身边商户。</p><div class="form card-surface"><van-field v-model="phone" type="tel" maxlength="11" label="手机号" placeholder="请输入手机号"/><van-field v-model="localAddress" readonly label="服务区域" placeholder="请选择所在区域" @click="showArea=true"><template #right-icon><img class="action-icon" :src="arrowIcon" alt="" /></template></van-field><van-button block round type="primary" size="large" @click="enter">{{ buttonText }}</van-button></div></section><van-popup v-model:show="showArea" round position="bottom"><button class="popup-close" aria-label="关闭" @click="showArea=false"><img :src="closeIcon" alt="" /></button><van-cascader v-model="areaValue" title="选择服务区域" :options="areaOptions" :closeable="false" @close="showArea=false" @finish="finish"/></van-popup></main></template>
<style scoped lang="scss">.start{display:flex;min-height:calc(100vh - 40px);flex-direction:column;align-items:center;padding:48px 16px 24px}.start h1{margin:40px 0 8px}.start>p{margin:0 0 24px;color:#7a8681}.form{width:100%}.form :deep(.van-cell){padding-right:0;padding-left:0}.form .van-button{margin-top:24px}.action-icon{display:block;width:18px;height:18px}.popup-close{position:absolute;z-index:2;top:12px;right:14px;padding:4px;background:transparent;border:0}.popup-close img{display:block;width:20px;height:20px}</style>
